rewrite-uri.template:
@{
        var p = context.Request.Url.Path;
        var marker = "/foundry";
        var idx = p.IndexOf(marker, System.StringComparison.OrdinalIgnoreCase);
        var rest = idx >= 0 ? p.Substring(idx + marker.Length) : p;
        if (!rest.StartsWith("/")) { rest = "/" + rest; }
        if (!rest.StartsWith("/openai", System.StringComparison.OrdinalIgnoreCase)) { rest = "/openai" + rest; }
        return rest;
    }
